from collections import OrderedDict

def cache_sim(capacity, ttl, ops):
    store = OrderedDict()  # key -> (value, write_time)
    results = []

    def is_expired(key, t):
        val, wt = store[key]
        return t >= wt + ttl

    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op

            # remove expired entries entirely (lazy cleanup)
            expired_keys = [k for k in store if t >= store[k][1] + ttl]
            for k in expired_keys:
                del store[k]

            if key in store:
                # existing, non-expired entry -> update
                del store[key]
                store[key] = (value, t)
            else:
                # new key (was absent, possibly after expiry cleanup)
                if len(store) >= capacity:
                    store.popitem(last=False)  # evict LRU
                store[key] = (value, t)
                store.move_to_end(key)

        elif op[0] == 'get':
            _, t, key = op
            if key in store:
                val, wt = store[key]
                if t >= wt + ttl:
                    del store[key]
                    results.append(-1)
                else:
                    store.move_to_end(key)
                    results.append(val)
            else:
                results.append(-1)

    return results

